// =====================================================================
// Le TODAS as NFS-e da Omie (paginado) e devolve o status de cada nota.
// Mode: Run Once for All Items
//
// CUSTO DE API (medido em 10/08/2026): 40 chamadas para 3.919 notas.
// A Omie LIMITA a pagina a ~100 registros mesmo pedindo 500 -- por isso 40
// paginas e nao 8. Segue barato: 40 contra ~3.900.
// NAO trocar por ObterNFSe: seria 1 chamada POR NOTA para o mesmo campo.
// O cStatusNFSe JA VEM nesta listagem.
//
// UMA EMPRESA SO (Sillion): confirmado com o Willian em 10/08/2026 -- a
// Sitrack NAO usa RF. RF e' controle da Vale, faturada pela Sillion. Logo
// nao ha' por que varrer a conta Omie da Sitrack: nenhuma nota dela vai
// aparecer em rf_nota. Se um dia a Vale for faturada pela Sitrack, basta
// rodar este mesmo fluxo com a outra app_key.
// =====================================================================

const cfg       = $input.first().json;
const appKey    = cfg.OMIE_APP_KEY;
const appSecret = cfg.OMIE_APP_SECRET;
const DRY_RUN   = String(cfg.DRY_RUN) === 'true';

if (!appKey || !appSecret || String(appKey).indexOf('COLE_') === 0) {
  throw new Error('Preencha OMIE_APP_KEY e OMIE_APP_SECRET no no Config.');
}

const POR_PAGINA = 500;   // a Omie reduz para ~100; manter nao custa nada
const PAUSA_MS   = 300;   // mesma pausa do fluxo "Popula tabela NF & boleto"

// RETOMADA: se a varredura morrer na pagina N, ponha N aqui e rode de novo.
// Repetir as 40 chamadas desde a 1 e' exatamente o consumo redundante que a
// Omie pune com 500. O que ja' foi lido nao precisa ser lido de novo.
const PAGINA_INICIAL = 1;

// Quantas vezes insistir na MESMA pagina antes de desistir, e quanto esperar.
// A espera crescente e' o que resolve "consumo redundante": nao e' insistencia
// cega, e' dar tempo para a Omie liberar.
const MAX_TENTATIVAS  = 3;
const ESPERA_RETRY_MS = [5000, 15000, 30000];

// A Omie devolve HTTP 500 com o MOTIVO no corpo (faultstring), mas o n8n
// mostra so' "Request failed with status code 500" e errorDetails vazio.
// Esta funcao cava o corpo nos varios lugares onde o n8n/axios o esconde.
function motivoOmie(e) {
  const candidatos = [
    e && e.response && e.response.data,
    e && e.response && e.response.body,
    e && e.cause && e.cause.response && e.cause.response.data,
    e && e.cause && e.cause.error,
    e && e.error,
    e && e.description,
  ];
  for (const c of candidatos) {
    if (!c) continue;
    let obj = c;
    if (typeof obj === 'string') {
      try { obj = JSON.parse(obj); } catch (_) { return obj.slice(0, 400); }
    }
    if (obj && (obj.faultstring || obj.faultcode)) {
      return String(obj.faultcode || '') + ' ' + String(obj.faultstring || '');
    }
    try { return JSON.stringify(obj).slice(0, 400); } catch (_) { /* segue */ }
  }
  return e && e.message ? String(e.message) : 'sem detalhe no corpo';
}

// arrow no topo: preserva o `this` do Code node dentro das funcoes abaixo
const chamar = (opcoes) => this.helpers.httpRequest(opcoes);

async function pedirPagina(p) {
  let ultimo = null;
  for (let t = 0; t < MAX_TENTATIVAS; t++) {
    try {
      return await chamar({
        method: 'POST',
        url: 'https://app.omie.com.br/api/v1/servicos/nfse/',
        headers: { 'Content-Type': 'application/json' },
        body: {
          call: 'ListarNFSEs',
          app_key: appKey,
          app_secret: appSecret,
          param: [{ nPagina: p, nRegPorPagina: POR_PAGINA }],
        },
        json: true,
      });
    } catch (e) {
      ultimo = e;
      console.warn('pagina ' + p + ', tentativa ' + (t + 1) + '/' + MAX_TENTATIVAS
        + ' falhou -> ' + motivoOmie(e));
      if (t < MAX_TENTATIVAS - 1) {
        await new Promise((s) => setTimeout(s, ESPERA_RETRY_MS[t]));
      }
    }
  }
  const err = new Error('A Omie recusou a pagina ' + p + ' em '
    + MAX_TENTATIVAS + ' tentativas. MOTIVO DA OMIE: ' + motivoOmie(ultimo)
    + ' | Se falar em consumo redundante, espere alguns minutos e rode de novo'
    + ' com PAGINA_INICIAL = ' + p + ' no topo deste no.');
  err.pagina = p;
  throw err;
}

const notas = [];
const vocabulario = {};
let chamadas = 0;
let pagina = PAGINA_INICIAL;
let totalPaginas = pagina;
let parcial = false;
let proxima_pagina = null;
let motivo_parada = null;

do {
  let r;
  try {
    r = await pedirPagina(pagina);
  } catch (e) {
    // Nao joga fora o que ja' foi lido: reprocessar do zero e' consumo
    // redundante. Devolve o parcial marcado, para o UPDATE aproveitar.
    if (!notas.length) throw e;
    parcial = true;
    proxima_pagina = e.pagina || pagina;
    motivo_parada = e.message;
    console.warn('PARCIAL: parou na pagina ' + proxima_pagina + ' com '
      + notas.length + ' nota(s) ja lida(s).');
    break;
  }

  chamadas++;
  totalPaginas = r.nTotPaginas || 1;
  const lote = r.nfseEncontradas || [];

  // IMPORTANTE: aqui NAO existe o filtro APENAS_EMITIDAS do fluxo diario.
  // As canceladas sao justamente o que interessa bloquear -- e por causa
  // desse filtro boa parte delas NUNCA entrou na tabela NF.
  for (const nf of lote) {
    const cab = nf && nf.Cabecalho ? nf.Cabecalho : {};
    const nIdNf = Number(cab.nCodNF);
    if (!Number.isFinite(nIdNf) || nIdNf <= 0) continue;

    const bruto = String(cab.cStatusNFSe == null ? '' : cab.cStatusNFSe).trim();
    const chave = bruto === '' ? '(vazio)' : bruto;
    vocabulario[chave] = (vocabulario[chave] || 0) + 1;

    notas.push({
      nIdNf: nIdNf,
      cNumNFSe: cab.nNumeroNFSe == null ? null : String(cab.nNumeroNFSe),
      cStatusNFSe: bruto === '' ? null : bruto,
      cDataEmissao: nf && nf.Emissao ? nf.Emissao.cDataEmissao : null,
    });
  }

  console.log('pagina ' + pagina + '/' + totalPaginas + ' - acumulado ' + notas.length);

  pagina++;
  if (pagina <= totalPaginas) await new Promise((s) => setTimeout(s, PAUSA_MS));
} while (pagina <= totalPaginas);

console.log('Vocabulario de status: ' + JSON.stringify(vocabulario));

return [{
  json: {
    DRY_RUN: DRY_RUN,
    chamadas_api: chamadas,
    pagina_inicial: PAGINA_INICIAL,
    total_paginas: totalPaginas,
    parcial: parcial,
    proxima_pagina: proxima_pagina,
    motivo_parada: motivo_parada,
    total_validas: notas.length,
    vocabulario: vocabulario,
    notas: notas,
  },
}];

// =====================================================================
// DRY RUN - nao toca no banco. Serve para 2 coisas:
//  1) revelar quais codigos de cStatusNFSe a Omie realmente usa
//     (a unica incognita que faltava para fechar o mapeamento);
//  2) provar que a paginacao roda dentro do limite de chamadas.
// =====================================================================

const d = $input.first().json;

// Vocabulario CONFIRMADO na execucao de 10/08/2026 (3.919 notas, 40 chamadas):
//   C =    63 notas -> cancelada
//   F = 3.856 notas -> faturada
// Nao existe codigo proprio para SUBSTITUIDA: na Omie a substituicao aparece
// como cancelamento + nota nova. Detectar substituicao = mesmo RF em 2 notas
// (dois registros em rf_nota com o mesmo rf).
const CONHECIDOS = { C: 'CANCELADA', F: 'FATURADA' };

const linhas = Object.entries(d.vocabulario || {})
  .sort(function (a, b) { return b[1] - a[1]; })
  .map(function (par) {
    return {
      codigo: par[0],
      quantidade: par[1],
      significado: CONHECIDOS[par[0]] || 'DESCONHECIDO -> mapear',
    };
  });

const desconhecidos = linhas.filter(function (l) {
  return l.significado.indexOf('DESCONHECIDO') === 0;
});

return [{
  json: {
    modo: 'DRY_RUN - nada foi gravado no banco',
    varredura: d.parcial
      ? 'PARCIAL - parou na pagina ' + d.proxima_pagina + ' de ' + d.total_paginas
        + '. Espere alguns minutos e rode de novo com PAGINA_INICIAL = '
        + d.proxima_pagina + ' no no Lista_Status_Omie.'
      : 'COMPLETA (' + d.total_paginas + ' pagina(s))',
    motivo_parada: d.motivo_parada || null,
    chamadas_api: d.chamadas_api,
    notas_lidas: d.total_validas,
    status_encontrados: linhas,
    precisa_mapear: desconhecidos.map(function (l) { return l.codigo; }),
    proximo_passo: desconhecidos.length
      ? 'Codigo novo encontrado. Complete o MAPA no no Montar_UPDATEs antes de virar DRY_RUN = false.'
      : 'Vocabulario conhecido. Pode virar DRY_RUN = false no no Config.',
    nota_de_cobertura:
      'notas_lidas > COUNT(*) da NF e ESPERADO: o fluxo diario descarta as canceladas '
      + '(APENAS_EMITIDAS), entao parte delas nunca entrou na NF. A rf_nota guarda nIdNf '
      + 'direto e nao depende da NF ter a linha.',
  },
}];

// =====================================================================
// Monta os UPDATE em LOTE da tabela rf_nota.
// Um UPDATE por lote de 500 notas (CASE ... WHEN), nao um UPDATE por linha.
// Mode: Run Once for All Items
// =====================================================================

// ========================= CONFIG =========================
// Tabela QUALIFICADA com o banco de proposito: a credencial MySQL do n8n
// ("MySQL faturamento") pode ter outro schema como default, e ai um
// "rf_nota" solto quebraria com "table doesn't exist". Conferido em
// 10/08/2026: a tabela existe em kvm4_db, ao lado de NF e rfs_faturados.
const TABELA = 'kvm4_db.rf_nota';
const LOTE   = 500;

// Codigo cru da Omie -> status de negocio.
// CONFIRMADO no DRY_RUN de 10/08/2026: o vocabulario tem SO estes dois
// codigos (C = 63 notas, F = 3.856 notas). Nao existe codigo de
// SUBSTITUIDA -- a substituicao aparece como cancelamento + nota nova,
// e se detecta pelo mesmo rf em duas linhas de rf_nota.
const MAPA = {
  C: 'CANCELADA',
  F: 'FATURADA',
};

// Codigo fora do MAPA cai aqui. Sob a regra do CFO os dois status
// bloqueiam, entao o bloqueio continua correto -- mas o rotulo exibido
// ficaria errado. Por isso qualquer codigo novo grita no log.
const PADRAO = 'FATURADA';
// ==========================================================

const d = $input.first().json;
const notas = Array.isArray(d.notas) ? d.notas : [];

if (!notas.length) {
  throw new Error('Nenhuma nota lida da Omie - confira as credenciais no no Config.');
}

const esc = function (s) {
  return String(s).replace(/\\/g, '\\\\').replace(/'/g, "''");
};

// Denuncia codigo fora do MAPA. Nao quebra o fluxo (o bloqueio segue certo),
// mas nao passa calado: um codigo novo rotulado errado engana quem le a tela.
const naoMapeados = {};
for (const n of notas) {
  if (n.cStatusNFSe != null && !MAPA[n.cStatusNFSe]) {
    naoMapeados[n.cStatusNFSe] = (naoMapeados[n.cStatusNFSe] || 0) + 1;
  }
}
if (Object.keys(naoMapeados).length) {
  console.warn('CODIGO FORA DO MAPA, gravado como ' + PADRAO + ': ' + JSON.stringify(naoMapeados));
}

const lotes = [];

for (let i = 0; i < notas.length; i += LOTE) {
  const bloco = notas.slice(i, i + LOTE);

  const ids = bloco
    .map(function (n) { return Number(n.nIdNf); })
    .filter(function (v) { return Number.isFinite(v) && v > 0; });

  if (!ids.length) continue;

  const caseCodigo = bloco.map(function (n) {
    const v = n.cStatusNFSe == null ? 'NULL' : "'" + esc(n.cStatusNFSe) + "'";
    return 'WHEN ' + Number(n.nIdNf) + ' THEN ' + v;
  }).join(' ');

  const caseNegocio = bloco.map(function (n) {
    const st = MAPA[n.cStatusNFSe] || PADRAO;
    return 'WHEN ' + Number(n.nIdNf) + " THEN '" + esc(st) + "'";
  }).join(' ');

  // Este fluxo SO atualiza linhas que JA EXISTEM na listinha (WHERE nIdNf IN).
  // Nota sem RF vinculado nao e afetada e nenhuma linha nova e criada aqui:
  // quem cria vinculo e a esteira VALE (ou o backfill), nunca este fluxo.
  lotes.push({
    json: {
      sql:
        'UPDATE ' + TABELA + ' SET ' +
        'cStatusNFSe = CASE nIdNf ' + caseCodigo + ' END, ' +
        'status_nota = CASE nIdNf ' + caseNegocio + ' END, ' +
        'status_em = NOW() ' +
        'WHERE nIdNf IN (' + ids.join(',') + ')',
      lote: lotes.length + 1,
      notas_no_lote: ids.length,
    },
  });
}

console.log(lotes.length + ' lote(s) de UPDATE montado(s) para ' + notas.length + ' nota(s).');
return lotes;
